def update_stories():
    with open("data/stories_full.json", "r", encoding="utf-8") as f:
        stories = json.load(f)
    
    # Update Story 37
    for idx, s in enumerate(stories):
        if s.get("storyNumber") == 37:
            stories[idx] = STORY_37_POLISHED
            print("Updated Story 37 in stories_full.json")
            break
            
    with open("data/stories_full.json", "w", encoding="utf-8") as f:
        json.dump(stories, f, ensure_ascii=False, indent=2)

if __name__ == "__main__":
    update_stories()
